"""Finance glossary used by the Learning Centre, tooltips and the offline research assistant.
Each entry: aliases, definition, formula (optional), interpretation, ratio key (to show the company's value)."""

GLOSSARY: dict[str, dict] = {
    "P/E ratio": {"aliases": ["pe", "p/e", "price to earnings", "price-earnings", "pe ratio"], "ratio": "pe",
                  "definition": "How many rupees investors pay for one rupee of the company's annual profit.",
                  "formula": "P/E = Share price / EPS = Market capitalisation / Net profit",
                  "interpretation": "A higher P/E implies the market expects faster growth or lower risk. Compare with the company's own history and close peers - not across unrelated sectors. Meaningless when earnings are negative."},
    "P/B ratio": {"aliases": ["pb", "p/b", "price to book", "price-to-book"], "ratio": "pb",
                  "definition": "Market value of equity relative to its accounting book value.",
                  "formula": "P/B = Market capitalisation / Shareholders' equity",
                  "interpretation": "Most useful for banks and asset-heavy businesses. A company earning ROE above its cost of equity can justify P/B above 1x."},
    "EV/EBITDA": {"aliases": ["ev/ebitda", "ev ebitda", "enterprise value multiple"], "ratio": "ev_ebitda",
                  "definition": "Value of the whole business (debt + equity - cash) relative to operating profit before depreciation.",
                  "formula": "EV/EBITDA = (Market cap + Borrowings - Cash) / EBITDA",
                  "interpretation": "Capital-structure neutral, so better than P/E for comparing companies with different debt levels. Not meaningful for banks."},
    "Enterprise value": {"aliases": ["ev", "enterprise value"],
                         "definition": "The theoretical takeover value of a business: what you would pay for the equity plus the debt you take on, less the cash you receive.",
                         "formula": "EV = Market capitalisation + Total borrowings - Cash & equivalents (+ minority interest, preference capital)",
                         "interpretation": "Used with operating metrics (EBITDA, sales) that belong to all capital providers."},
    "ROE": {"aliases": ["roe", "return on equity"], "ratio": "roe",
            "definition": "Profit earned for each rupee of shareholders' capital.",
            "formula": "ROE = Net profit / Average shareholders' equity",
            "interpretation": "Sustained ROE above the cost of equity (~12-14% in India) indicates value creation. Use DuPont analysis to check whether it comes from margins, efficiency or leverage."},
    "ROCE": {"aliases": ["roce", "return on capital employed"], "ratio": "roce",
             "definition": "Pre-tax operating return on all long-term capital - equity and debt.",
             "formula": "ROCE = EBIT / Capital employed; Capital employed = Total assets - Current liabilities",
             "interpretation": "Measures business quality independent of financing. Compare with the pre-tax cost of capital; consistently high ROCE often signals a competitive advantage."},
    "DuPont analysis": {"aliases": ["dupont", "du pont"],
                        "definition": "Breaks ROE into profitability, efficiency and leverage.",
                        "formula": "ROE = Net margin × Asset turnover × Equity multiplier",
                        "interpretation": "ROE rising because of leverage is lower quality than ROE rising from margins or asset turnover."},
    "Debt to equity": {"aliases": ["debt to equity", "d/e", "debt-equity", "leverage", "gearing"], "ratio": "debt_to_equity",
                       "definition": "Borrowings relative to shareholders' funds.",
                       "formula": "D/E = Total borrowings / Shareholders' equity",
                       "interpretation": "Higher leverage magnifies returns and risk. Acceptable levels depend on the stability of cash flows (utilities tolerate more than cyclicals)."},
    "Interest coverage": {"aliases": ["interest coverage", "icr", "times interest earned"], "ratio": "interest_coverage",
                          "definition": "How many times operating profit covers interest expense.",
                          "formula": "Interest coverage = EBIT / Finance costs",
                          "interpretation": "Below ~1.5x is a warning sign; lenders often look for 3x or more."},
    "Current ratio": {"aliases": ["current ratio", "liquidity ratio"], "ratio": "current_ratio",
                      "definition": "Short-term assets available to meet short-term obligations.",
                      "formula": "Current ratio = Current assets / Current liabilities",
                      "interpretation": "Below 1x can indicate liquidity pressure, although some businesses (e.g. FMCG with supplier credit) operate below 1x safely."},
    "Free cash flow": {"aliases": ["fcf", "free cash flow"], "ratio": "fcf_margin",
                       "definition": "Cash generated by operations after the investment needed to maintain and grow the asset base.",
                       "formula": "FCF = Cash flow from operations - Capital expenditure",
                       "interpretation": "Funds dividends, buybacks and debt repayment. Persistent negative FCF means growth depends on external capital."},
    "EBITDA": {"aliases": ["ebitda", "operating profit before depreciation"],
               "definition": "Earnings before interest, tax, depreciation and amortisation - a proxy for operating cash profit.",
               "formula": "EBITDA = EBIT + Depreciation & amortisation",
               "interpretation": "Ignores capital intensity; always check capex alongside it."},
    "EPS": {"aliases": ["eps", "earnings per share"], "ratio": "eps",
            "definition": "Net profit attributable to each equity share.",
            "formula": "EPS = Net profit attributable to shareholders / Weighted average shares (diluted EPS includes convertible instruments)",
            "interpretation": "Growth in EPS (not just profit) shows whether shareholders benefit after dilution."},
    "DCF": {"aliases": ["dcf", "discounted cash flow", "intrinsic value", "fcff"],
            "definition": "Values a business as the present value of the cash flows it will generate in future.",
            "formula": "Value = Σ FCFF_t / (1 + WACC)^t + Terminal value / (1 + WACC)^N; TV = FCFF_N × (1 + g) / (WACC - g)",
            "interpretation": "Highly sensitive to WACC and terminal growth - always show scenarios and a sensitivity table."},
    "WACC": {"aliases": ["wacc", "weighted average cost of capital", "cost of capital"],
             "definition": "The blended required return of equity and debt investors - the discount rate in an FCFF DCF.",
             "formula": "WACC = We × Ke + Wd × Kd × (1 - tax rate)",
             "interpretation": "Weights should be at market values. A 1 percentage-point change can move DCF value substantially."},
    "CAPM": {"aliases": ["capm", "cost of equity", "capital asset pricing model"],
             "definition": "Estimates the return equity investors require for bearing market (systematic) risk.",
             "formula": "Ke = Risk-free rate + β × Equity risk premium",
             "interpretation": "In India the risk-free rate is usually proxied by the 10-year G-sec yield."},
    "Beta": {"aliases": ["beta"],
             "definition": "Sensitivity of a stock's returns to market returns.",
             "formula": "β = Cov(stock returns, market returns) / Var(market returns)",
             "interpretation": "β > 1 moves more than the market; β < 1 less. It captures only systematic risk."},
    "Terminal growth": {"aliases": ["terminal growth", "perpetual growth", "gordon growth"],
                        "definition": "The constant growth rate assumed for cash flows after the explicit forecast period.",
                        "formula": "TV = FCF_(N+1) / (WACC - g)",
                        "interpretation": "Should not exceed long-run nominal GDP growth; must be below WACC."},
    "RSI": {"aliases": ["rsi", "relative strength index"],
            "definition": "Momentum oscillator (0-100) comparing recent gains with recent losses.",
            "formula": "RSI = 100 - 100 / (1 + average gain / average loss), usually over 14 days (Wilder smoothing)",
            "interpretation": "Above 70 is conventionally 'overbought', below 30 'oversold' - descriptive readings, not signals on their own."},
    "MACD": {"aliases": ["macd", "moving average convergence divergence"],
             "definition": "Trend-momentum indicator based on the gap between two exponential moving averages.",
             "formula": "MACD = EMA(12) - EMA(26); Signal = EMA(9) of MACD",
             "interpretation": "MACD crossing above its signal line indicates strengthening upward momentum."},
    "Moving average": {"aliases": ["moving average", "sma", "ema", "200 dma", "50 dma"],
                       "definition": "Average closing price over a rolling window, smoothing out daily noise.",
                       "formula": "SMA(n) = sum of last n closes / n",
                       "interpretation": "Price above the 200-day average is commonly read as a long-term uptrend."},
    "Volatility": {"aliases": ["volatility", "standard deviation"],
                   "definition": "Dispersion of returns - a common measure of total risk.",
                   "formula": "Annualised volatility = standard deviation of daily returns × √252",
                   "interpretation": "Higher volatility means a wider range of likely outcomes."},
    "Piotroski F-score": {"aliases": ["piotroski", "f-score", "f score"],
                          "definition": "Nine binary tests of profitability, leverage/liquidity and operating efficiency.",
                          "formula": "Score 0-9; one point per test passed",
                          "interpretation": "8-9 indicates strong and improving fundamentals; 0-2 weak."},
    "Altman Z-score": {"aliases": ["altman", "z-score", "z score"],
                       "definition": "A model combining balance-sheet and earnings ratios to screen for financial distress.",
                       "formula": "Z'' = 6.56·WC/TA + 3.26·RE/TA + 6.72·EBIT/TA + 1.05·Equity/TL",
                       "interpretation": "Above 2.6 safe, below 1.1 distress zone. A screening tool, not a prediction."},
    "Consolidated vs standalone": {"aliases": ["consolidated", "standalone"],
                                   "definition": "Standalone statements cover only the listed company; consolidated statements add its subsidiaries (and share of associates/JVs).",
                                   "formula": "—",
                                   "interpretation": "Use consolidated figures for groups with significant subsidiaries; never compare a consolidated figure with a standalone one."},
    "Market capitalisation": {"aliases": ["market cap", "market capitalisation", "market capitalization", "mcap"],
                              "definition": "Total market value of a company's equity shares.",
                              "formula": "Market cap = Share price × Shares outstanding",
                              "interpretation": "SEBI classifies large-cap as the top 100 listed companies by market cap, mid-cap 101-250 and small-cap 251 onwards."},
    "Dividend yield": {"aliases": ["dividend yield"],
                       "definition": "Annual dividend per share as a percentage of the share price.",
                       "formula": "Dividend yield = Dividend per share / Share price",
                       "interpretation": "Read with the payout ratio and cash flows to judge sustainability."},
    "Working capital": {"aliases": ["working capital", "nwc", "cash conversion cycle"],
                        "definition": "Operating current assets minus operating current liabilities - cash tied up in running the business.",
                        "formula": "Cash conversion cycle = Inventory days + Receivable days - Payable days",
                        "interpretation": "Rising working capital absorbs cash and can signal channel stuffing or collection problems."},
    "Research analyst": {"aliases": ["research analyst", "sebi ra", "ra regulations"],
                         "definition": "In India, a person or entity preparing or publishing research reports or making buy/sell/hold recommendations on securities must be registered with SEBI under the SEBI (Research Analysts) Regulations, 2014.",
                         "formula": "—",
                         "interpretation": "Registered analysts must disclose conflicts of interest (e.g. holdings in the covered company) and maintain research records. EquityPilot is an educational tool and does not issue recommendations."},
}


def find_term(text: str) -> str | None:
    t = f" {text.lower()} "
    best, best_len = None, 0
    for name, e in GLOSSARY.items():
        for a in [name.lower()] + e["aliases"]:
            if (f" {a} " in t or f" {a}?" in t or f" {a}," in t or f"({a})" in t or f" {a}." in t) and len(a) > best_len:
                best, best_len = name, len(a)
    return best
